1	import { writeFileSync, copyFileSync, unlinkSync, existsSync, statSync, readdirSync } from 'fs';
2	import { resolve, dirname, basename, extname } from 'path';
3	import { fileURLToPath } from 'url';
4	
5	// ESM compatibility - __dirname is not available in ESM
6	const __filename = fileURLToPath(import.meta.url);
7	const __dirname = dirname(__filename);
8	
9	/**
10	 * Utilities for creating and managing test files.
11	 * Files are created in tests/web-e2e/fixtures/files/ and tracked for cleanup.
12	 *
13	 * Static fixtures (test-image.png, test-document.pdf, test-file.txt)
14	 * are committed to the repo. Generated files use unique names and are
15	 * cleaned up after each test run.
16	 */
17	
18	const FIXTURES_DIR = resolve(__dirname, '../fixtures/files');
19	const createdFiles: string[] = [];
20	
21	/** Names of committed fixture files — never overwrite or delete these. */
22	const COMMITTED_FIXTURES = new Set(readdirSync(FIXTURES_DIR).filter((f) => !f.startsWith('.')));
23	
24	interface TestTextFile {
25	  name: string;
26	  content: string;
27	  path: string;
28	}
29	
30	interface TestBinaryFile {
31	  name: string;
32	  path: string;
33	  sizeKb: number;
34	}
35	
36	/**
37	 * Creates a test text file with specified name and content.
38	 * File is tracked for cleanup.
39	 *
40	 * @param name - Optional file name (defaults to test-file-{timestamp}.txt)
41	 * @param content - Optional file content (defaults to test content with timestamp)
42	 * @returns Object with file name, content, and absolute path
43	 */
44	export function createTestTextFile(name?: string, content?: string): TestTextFile {
45	  const timestamp = Date.now();
46	  const fileName = name || `test-file-${timestamp}.txt`;
47	  if (COMMITTED_FIXTURES.has(fileName)) {
48	    throw new Error(`Refusing to overwrite committed fixture: ${fileName}`);
49	  }
50	  const fileContent =
51	    content || `Test file created at ${new Date(timestamp).toISOString()}\nThis is test content.`;
52	  const filePath = resolve(FIXTURES_DIR, fileName);
53	
54	  writeFileSync(filePath, fileContent, 'utf-8');
55	  createdFiles.push(filePath);
56	
57	  return {
58	    name: fileName,
59	    content: fileContent,
60	    path: filePath,
61	  };
62	}
63	
64	/**
65	 * Creates a test binary file with specified size.
66	 * File is filled with random bytes and tracked for cleanup.
67	 *
68	 * @param sizeKb - Size of file in kilobytes
69	 * @param name - Optional file name (defaults to test-binary-{timestamp}.bin)
70	 * @returns Object with file name, absolute path, and size
71	 */
72	export function createTestBinaryFile(sizeKb: number, name?: string): TestBinaryFile {
73	  const timestamp = Date.now();
74	  const fileName = name || `test-binary-${timestamp}.bin`;
75	  if (COMMITTED_FIXTURES.has(fileName)) {
76	    throw new Error(`Refusing to overwrite committed fixture: ${fileName}`);
77	  }
78	  const filePath = resolve(FIXTURES_DIR, fileName);
79	
80	  // Create buffer with random bytes
81	  const buffer = Buffer.alloc(sizeKb * 1024);
82	  for (let i = 0; i < buffer.length; i++) {
83	    buffer[i] = Math.floor(Math.random() * 256);
84	  }
85	
86	  writeFileSync(filePath, buffer);
87	  createdFiles.push(filePath);
88	
89	  return {
90	    name: fileName,
91	    path: filePath,
92	    sizeKb,
93	  };
94	}
95	
96	/**
97	 * Creates a test image file by copying the static PNG fixture.
98	 * The fixture is a valid 1x1 green PNG (69 bytes).
99	 * File is tracked for cleanup.
100	 *
101	 * @param name - Optional file name (defaults to test-image-{timestamp}.png)
102	 * @returns Object with file name and absolute path
103	 */
104	export function createTestImageFile(name?: string): TestBinaryFile {
105	  const timestamp = Date.now();
106	  const fileName = name || `test-image-${timestamp}.png`;
107	  if (COMMITTED_FIXTURES.has(fileName)) {
108	    throw new Error(`Refusing to overwrite committed fixture: ${fileName}`);
109	  }
110	  const filePath = resolve(FIXTURES_DIR, fileName);
111	  const fixturePath = resolve(FIXTURES_DIR, 'test-image.png');
112	
113	  copyFileSync(fixturePath, filePath);
114	  createdFiles.push(filePath);
115	
116	  return {
117	    name: fileName,
118	    path: filePath,
119	    sizeKb: 0,
120	  };
121	}
122	
123	/**
124	 * Removes all test files created during the test session.
125	 * Should be called in afterEach or afterAll hooks.
126	 */
127	export function cleanupTestFiles(): void {
128	  for (const filePath of createdFiles) {
129	    try {
130	      if (existsSync(filePath)) {
131	        unlinkSync(filePath);
132	      }
133	    } catch (error) {
134	      console.warn(`Failed to cleanup test file ${filePath}:`, error);
135	    }
136	  }
137	  createdFiles.length = 0; // Clear the array
138	}
139	
140	/**
141	 * Get absolute path for a file in the test fixtures directory.
142	 *
143	 * @param name - File name
144	 * @returns Absolute path to the file
145	 */
146	export function getTestFilePath(name: string): string {
147	  return resolve(FIXTURES_DIR, name);
148	}
149	
150	/**
151	 * Creates a test media file by copying a committed fixture (e.g. test-video.mp4)
152	 * to a unique name. File is tracked for cleanup.
153	 *
154	 * @param sourceFixture - Name of the committed fixture file (e.g. 'test-video.mp4')
155	 * @param name - Optional destination file name (defaults to test-media-{timestamp}.{ext})
156	 * @returns Object with file name, absolute path, and size in KB
157	 */
158	export function createTestMediaFile(sourceFixture: string, name?: string): TestBinaryFile {
159	  const timestamp = Date.now();
160	  const safeSource = basename(sourceFixture);
