  /** 0-100, tracks SW encrypted file fetch progress */
  decryptProgress: number;
  /** Whether SW is active and can handle requests */
  isSwReady: boolean;
  /** Whether the file uses CTR encryption (streaming-eligible) */
  isCtr: boolean;
  /** Download the full decrypted file */
  handleDownload: () => void;
