1	/// <reference lib="webworker" />
2	/**
3	 * Service Worker for transparent AES-CTR media decryption.
4	 *
5	 * Intercepts fetch requests to /decrypt-stream/* URLs, fetches encrypted
6	 * content from the API, decrypts with AES-CTR, and returns proper HTTP
7	 * responses (200/206). This makes encryption invisible to <video>/<audio>.
8	 */
9	
10	// Cast self to ServiceWorkerGlobalScope (available with WebWorker lib)
11	const sw = self as unknown as ServiceWorkerGlobalScope;
12	
13	// ---------------------------------------------------------------------------
14	// Types
15	// ---------------------------------------------------------------------------
16	
17	/**
18	 * Security note: StreamContext holds hex-encoded AES-256 key material in SW memory
19	 * for the lifetime of an active stream. Keys are cleared when the stream is
20	 * unregistered via the 'unregister-stream' message. The SW is a trusted context
21	 * for active playback sessions only.
22	 */
23	type StreamContext = {
24	  fileKey: string; // hex-encoded AES-256 key
25	  iv: string; // hex-encoded 16-byte CTR IV
26	  cid: string; // IPFS CID of encrypted content
27	  totalSize: number; // Original file size in bytes
28	  mimeType: string; // MIME type for response
29	};
30	
31	type RegisterStreamMessage = {
32	  type: 'register-stream';
33	  fileMetaIpnsName: string;
34	} & StreamContext;
35	
36	type UnregisterStreamMessage = {
37	  type: 'unregister-stream';
38	  fileMetaIpnsName: string;
39	};
40	
41	type UpdateTokenMessage = {
42	  type: 'update-token';
43	  token: string;
44	};
45	
46	type SetApiBaseMessage = {
47	  type: 'set-api-base';
48	  url: string;
49	};
50	
51	type SwMessage =
52	  | RegisterStreamMessage
53	  | UnregisterStreamMessage
54	  | UpdateTokenMessage
55	  | SetApiBaseMessage;
56	
57	// ---------------------------------------------------------------------------
58	// State
59	// ---------------------------------------------------------------------------
60	
61	/** Active decrypt contexts keyed by fileMetaIpnsName */
62	const streamRegistry = new Map<string, StreamContext>();
63	
64	/** Maximum number of encrypted files to cache in SW memory */
65	const MAX_CACHE_ENTRIES = 5;
66	
67	/** In-memory cache of fetched encrypted files (full file per CID) */
68	const encryptedCache = new Map<string, Uint8Array>();
69	
70	function cacheSet(key: string, data: Uint8Array): void {
71	  if (encryptedCache.size >= MAX_CACHE_ENTRIES) {
72	    // Evict oldest entry (Map preserves insertion order)
73	    const oldest = encryptedCache.keys().next().value;
74	    if (oldest !== undefined) encryptedCache.delete(oldest);
75	  }
76	  encryptedCache.set(key, data);
77	}
78	
79	/** Auth token for API requests */
80	let authToken: string | null = null;
81	
82	/** API base URL (e.g. http://localhost:3000) */
83	let apiBaseUrl = '';
84	
85	// ---------------------------------------------------------------------------
86	// Helpers
87	// ---------------------------------------------------------------------------
88	
89	function hexToBytes(hex: string): Uint8Array {
90	  const bytes = new Uint8Array(hex.length / 2);
91	  for (let i = 0; i < hex.length; i += 2) {
92	    bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
93	  }
94	  return bytes;
95	}
96	
97	/**
98	 * Decrypt an arbitrary byte range from AES-CTR-encrypted data.
99	 *
100	 * Computes the block-aligned slice and counter offset, decrypts via
101	 * Web Crypto, and extracts the exact requested bytes.
102	 */
103	async function decryptRange(
104	  encrypted: Uint8Array,
105	  keyHex: string,
106	  ivHex: string,
107	  start: number,
108	  end: number
109	): Promise<Uint8Array> {
110	  const keyBytes = hexToBytes(keyHex);
111	  const ivBytes = hexToBytes(ivHex);
112	
113	  const blockSize = 16;
114	  const startBlock = Math.floor(start / blockSize);
115	
116	  // Build counter for the starting block
117	  const counter = new Uint8Array(16);
118	  counter.set(ivBytes.subarray(0, 8), 0); // 8-byte nonce
119	  const baseCounter = new DataView(
120	    ivBytes.buffer as ArrayBuffer,
121	    ivBytes.byteOffset,
122	    ivBytes.byteLength
123	  ).getBigUint64(8, false);
124	  const counterView = new DataView(
125	    counter.buffer as ArrayBuffer,
126	    counter.byteOffset,
127	    counter.byteLength
128	  );
129	  counterView.setBigUint64(8, baseCounter + BigInt(startBlock), false);
130	
131	  // Import key
132	  const cryptoKey = await crypto.subtle.importKey(
133	    'raw',
134	    keyBytes as BufferSource,
135	    { name: 'AES-CTR' },
136	    false,
137	    ['decrypt']
138	  );
139	
140	  // Block-aligned range
141	  const blockAlignedStart = startBlock * blockSize;
142	  const blockAlignedEnd = Math.min((Math.floor(end / blockSize) + 1) * blockSize, encrypted.length);
143	
144	  // Decrypt block-aligned slice
145	  const slice = encrypted.subarray(blockAlignedStart, blockAlignedEnd);
146	  const decrypted = await crypto.subtle.decrypt(
147	    { name: 'AES-CTR', counter: counter as BufferSource, length: 64 },
148	    cryptoKey,
149	    slice as BufferSource
150	  );
151	
152	  // Extract exact requested bytes
153	  const offsetInFirstBlock = start - blockAlignedStart;
154	  const requestedLength = end - start + 1;
155	  return new Uint8Array(decrypted).subarray(
156	    offsetInFirstBlock,
157	    offsetInFirstBlock + requestedLength
158	  );
159	}
160	
161	/**
162	 * Post a message to all controlled clients.
163	 */
164	async function postToClients(message: unknown): Promise<void> {
165	  const allClients = await sw.clients.matchAll({ type: 'window' });
166	  for (const client of allClients) {
167	    client.postMessage(message);
168	  }
169	}
170	
171	// ---------------------------------------------------------------------------
172	// Message handler (main thread -> SW)
173	// ---------------------------------------------------------------------------
174	
175	sw.addEventListener('message', (event) => {
176	  const data = event.data as SwMessage;
177	
178	  switch (data.type) {
179	    case 'register-stream': {
180	      const { fileMetaIpnsName, fileKey, iv, cid, totalSize, mimeType } =
181	        data as RegisterStreamMessage;
182	      streamRegistry.set(fileMetaIpnsName, {
183	        fileKey,
184	        iv,
185	        cid,
186	        totalSize,
187	        mimeType,
188	      });
189	      break;
190	    }
191	
192	    case 'unregister-stream': {
193	      const { fileMetaIpnsName } = data as UnregisterStreamMessage;
194	      streamRegistry.delete(fileMetaIpnsName);
195	      encryptedCache.delete(fileMetaIpnsName);
196	      break;
197	    }
198	
199	    case 'update-token': {
200	      authToken = (data as UpdateTokenMessage).token;
201	      break;
202	    }
203	
204	    case 'set-api-base': {
205	      apiBaseUrl = (data as SetApiBaseMessage).url;
206	      break;
207	    }
208	  }
209	});
210	
211	// ---------------------------------------------------------------------------
212	// Lifecycle
213	// ---------------------------------------------------------------------------
214	
215	sw.addEventListener('install', () => {
216	  void sw.skipWaiting();
217	});
218	
219	sw.addEventListener('activate', (event) => {
220	  event.waitUntil(sw.clients.claim());
221	});
222	
223	// ---------------------------------------------------------------------------
224	// Fetch handler
225	// ---------------------------------------------------------------------------
226	
227	sw.addEventListener('fetch', (event) => {
228	  const url = new URL(event.request.url);
229	
230	  // Only intercept /decrypt-stream/* URLs
231	  if (!url.pathname.startsWith('/decrypt-stream/')) return;
232	
233	  const ipnsName = url.pathname.split('/decrypt-stream/')[1];
234	  if (!ipnsName) {
235	    event.respondWith(new Response('Not found', { status: 404 }));
236	    return;
237	  }
238	
239	  const ctx = streamRegistry.get(ipnsName);
240	  if (!ctx) {
241	    event.respondWith(new Response('Not found', { status: 404 }));
242	    return;
243	  }
244	
245	  event.respondWith(handleDecryptStream(event.request, ctx, ipnsName));
246	});
247	
248	// ---------------------------------------------------------------------------
249	// Decrypt stream handler
250	// ---------------------------------------------------------------------------
251	
252	async function handleDecryptStream(
253	  request: Request,
254	  ctx: StreamContext,
255	  cacheKey: string
256	): Promise<Response> {
257	  // 1. Get encrypted data (from cache or fetch)
258	  let encrypted = encryptedCache.get(cacheKey);
259	
260	  if (!encrypted) {
261	    const fetchUrl = `${apiBaseUrl}/ipfs/${ctx.cid}`;
262	    const fetchHeaders: Record<string, string> = {};
263	    if (authToken) {
264	      fetchHeaders['Authorization'] = `Bearer ${authToken}`;
265	    }
266	
267	    let response: Response;
268	    const controller = new AbortController();
269	    const timeoutId = setTimeout(() => controller.abort(), 60_000);
270	    try {
271	      response = await fetch(fetchUrl, { headers: fetchHeaders, signal: controller.signal });
272	    } catch {
273	      return new Response('Failed to fetch encrypted content', { status: 502 });
274	    } finally {
275	      clearTimeout(timeoutId);
276	    }
277	
278	    if (response.status === 401) {
279	      // Request token refresh from main thread
280	      await postToClients({ type: 'token-expired' });
281	      return new Response('Unauthorized', { status: 401 });
282	    }
283	
284	    if (!response.ok) {
285	      await postToClients({
286	        type: 'fetch-error',
287	        fileMetaIpnsName: cacheKey,
288	        error: `HTTP ${response.status}`,
289	      });
290	      return new Response('Failed to fetch encrypted content', {
291	        status: response.status,
292	      });
293	    }
294	
295	    // Stream the response body to track download progress
296	    const contentLength = parseInt(response.headers.get('Content-Length') || '0', 10);
297	    const total = contentLength || ctx.totalSize;
298	
299	    if (response.body) {
300	      const reader = response.body.getReader();
301	      const chunks: Uint8Array[] = [];
302	      let loaded = 0;
303	
304	      for (;;) {
305	        const { done, value } = await reader.read();
306	        if (done) break;
307	        chunks.push(value);
308	        loaded += value.length;
309	        await postToClients({
310	          type: 'fetch-progress',
311	          fileMetaIpnsName: cacheKey,
312	          loaded,
313	          total,
314	        });
315	      }
316	
317	      // Combine chunks into a single Uint8Array
318	      const combined = new Uint8Array(loaded);
319	      let offset = 0;
320	      for (const chunk of chunks) {
321	        combined.set(chunk, offset);
322	        offset += chunk.length;
323	      }
324	      encrypted = combined;
325	    } else {
326	      // Fallback: no streaming body (shouldn't happen, but handle gracefully)
327	      encrypted = new Uint8Array(await response.arrayBuffer());
328	    }
329	
330	    cacheSet(cacheKey, encrypted);
331	    await postToClients({
332	      type: 'fetch-complete',
333	      fileMetaIpnsName: cacheKey,
334	    });
335	  }
336	
337	  // 2. Parse Range header
338	  const rangeHeader = request.headers.get('Range');
339	  let start = 0;
340	  let end = ctx.totalSize - 1;
341	  let isRangeRequest = false;
342	
343	  if (rangeHeader) {
344	    // Handle suffix range: bytes=-N (last N bytes)
345	    const suffixMatch = rangeHeader.match(/bytes=-(\d+)/);
346	    const prefixMatch = rangeHeader.match(/bytes=(\d+)-(\d*)/);
347	
348	    if (suffixMatch) {
349	      isRangeRequest = true;
350	      const suffixLength = parseInt(suffixMatch[1], 10);
351	      start = Math.max(0, ctx.totalSize - suffixLength);
352	      end = ctx.totalSize - 1;
353	    } else if (prefixMatch) {
354	      isRangeRequest = true;
355	      start = parseInt(prefixMatch[1], 10);
356	      end = prefixMatch[2] ? parseInt(prefixMatch[2], 10) : ctx.totalSize - 1;
357	    }
358	
359	    if (isRangeRequest) {
360	      // Clamp to valid range
361	      if (end >= ctx.totalSize) end = ctx.totalSize - 1;
362	      if (start > end) {
363	        return new Response('Range Not Satisfiable', {
364	          status: 416,
365	          headers: {
366	            'Content-Range': `bytes */${ctx.totalSize}`,
367	          },
368	        });
369	      }
370	    }
371	  }
372	
373	  // 3. Decrypt the requested range
374	  let decrypted: Uint8Array;
375	  try {
376	    decrypted = await decryptRange(encrypted, ctx.fileKey, ctx.iv, start, end);
377	  } catch {
378	    return new Response('Decryption failed', { status: 500 });
379	  }
380	
381	  // 4. Build response
382	  const headers: Record<string, string> = {
383	    'Content-Type': ctx.mimeType,
384	    'Content-Length': String(decrypted.byteLength),
385	    'Accept-Ranges': 'bytes',
386	  };
387	
388	  // Slice to exact ArrayBuffer for Response body (TS 5.9 Uint8Array<ArrayBufferLike> compat)
389	  const body = (decrypted.buffer as ArrayBuffer).slice(
390	    decrypted.byteOffset,
391	    decrypted.byteOffset + decrypted.byteLength
392	  );
393	
394	  if (isRangeRequest) {
395	    headers['Content-Range'] = `bytes ${start}-${end}/${ctx.totalSize}`;
396	    return new Response(body, { status: 206, headers });
397	  }
398	
399	  return new Response(body, { status: 200, headers });
400	}
